-- Phase 4: representatives, transfers, settlements, sync, notifications
CREATE TABLE representative_profiles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, employee_id UUID NOT NULL UNIQUE, user_id UUID, warehouse_id UUID NOT NULL UNIQUE, is_active BOOLEAN NOT NULL DEFAULT true, max_offline_credit NUMERIC(19,4) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE stock_transfers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, number INT, from_warehouse_id UUID NOT NULL, to_warehouse_id UUID NOT NULL, status TEXT NOT NULL DEFAULT 'draft', business_date DATE NOT NULL, dispatched_by UUID, received_by UUID, idempotency_key TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (tenant_id, idempotency_key));
CREATE TABLE transfer_lines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, transfer_id UUID NOT NULL REFERENCES stock_transfers(id) ON DELETE CASCADE, product_id UUID NOT NULL, lot_id UUID, dispatched_qty NUMERIC(19,6) NOT NULL, received_qty NUMERIC(19,6) NOT NULL DEFAULT 0, disputed_qty NUMERIC(19,6) NOT NULL DEFAULT 0, dispute_reason TEXT);
CREATE TABLE settlements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, employee_id UUID NOT NULL, warehouse_id UUID NOT NULL, status TEXT NOT NULL DEFAULT 'requested', period_start DATE NOT NULL, period_end DATE NOT NULL, expected_cash NUMERIC(19,4) NOT NULL DEFAULT 0, counted_cash NUMERIC(19,4), cash_handed_over NUMERIC(19,4), finalized_by UUID, finalized_at TIMESTAMPTZ, created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE settlement_lines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, settlement_id UUID NOT NULL REFERENCES settlements(id) ON DELETE CASCADE, product_id UUID NOT NULL, expected_qty NUMERIC(19,6) NOT NULL, counted_qty NUMERIC(19,6));
CREATE TABLE settlement_exceptions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, settlement_id UUID NOT NULL REFERENCES settlements(id) ON DELETE CASCADE, kind TEXT NOT NULL, product_id UUID, qty NUMERIC(19,6), amount NUMERIC(19,4), status TEXT NOT NULL DEFAULT 'under_investigation', decision_by UUID, decision_reason TEXT, adjustment_journal_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sync_operations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, device_id UUID, user_id UUID NOT NULL, client_op_id TEXT NOT NULL, type TEXT NOT NULL, payload JSONB NOT NULL, payload_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'received', result_document_id TEXT, error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (tenant_id, user_id, client_op_id));
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, user_id UUID NOT NULL, type TEXT NOT NULL, title TEXT NOT NULL, body TEXT, ref_type TEXT, ref_id TEXT, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX notifications_user_read_idx ON notifications (tenant_id, user_id, read_at);
DO $$ DECLARE t TEXT; BEGIN
  FOREACH t IN ARRAY ARRAY['representative_profiles','stock_transfers','transfer_lines','settlements','settlement_lines','settlement_exceptions','sync_operations','notifications'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id::text = current_setting(''app.tenant_id'', true) OR current_setting(''app.platform_access'', true) = ''on'') WITH CHECK (tenant_id::text = current_setting(''app.tenant_id'', true) OR current_setting(''app.platform_access'', true) = ''on'')', t);
  END LOOP;
END $$;
